+static id<MTLBuffer> qwen4_expanded_iq2(const void *map, uint64_t size, uint64_t offset,
+        uint32_t experts, uint32_t in_dim, uint32_t rows) {
+    const uint32_t mode = (uint32_t)ds4_gpu_env_u64("DS4_QWEN4_EXPAND_IQ2", 1u, 1u, 2u);
+    const uint32_t stride = mode == 2u ? 12u : 36u;
+    const uint64_t blocks = (uint64_t)experts * rows * (in_dim / 32u);
+    if (!blocks || in_dim % 256u || blocks > UINT32_MAX || blocks * stride > [g_device maxBufferLength]) return nil;
+    if (!g_qwen4_expanded_iq2) g_qwen4_expanded_iq2 = [NSMutableDictionary dictionary];
+    NSString *key = [NSString stringWithFormat:@"%u:%p:%llu:%llu:%llu", stride, map, (unsigned long long)size,
+        (unsigned long long)offset, (unsigned long long)blocks];
+    id<MTLBuffer> buffer = g_qwen4_expanded_iq2[key];
+    if (buffer) return buffer;
+    qwen4_bind b[2];
+    if (!qwen4_bind_weight(&b[0], map, size, offset, blocks / 8u * 66u, "IQ2 expansion source")) return nil;
+    buffer = [g_device newBufferWithLength:(NSUInteger)(blocks * stride) options:MTLResourceStorageModeShared];
+    if (!buffer) return nil;
+    buffer.label = @"Qwen expanded IQ2 experts";
+    b[1].buf = buffer; b[1].off = 0;
+    const uint32_t count = (uint32_t)blocks;
+    const uint32_t args[2] = {count, mode};
+    if (!qwen4_dispatch(QWEN4_K_EXPAND_IQ2, args, sizeof(args), b, 2,
+        MTLSizeMake((count + 127u) / 128u, 1, 1), MTLSizeMake(128, 1, 1), 0)) return nil;
+    g_qwen4_expanded_iq2[key] = buffer;
+    return buffer;
