+
+kernel void kernel_qwen4_down_reduce(
+    constant ds4_metal_args_qwen4_moe &args,
+    device const char *down, device const int *selected, device const float *mid,
+    device const char *sh_down, device const float *weights, device const float *sh_gate,
+    device float *out, device float *R, device const float *inj,
+    uint group [[threadgroup_position_in_grid]], ushort tid [[thread_index_in_threadgroup]],
+    ushort lane [[thread_index_in_simdgroup]], ushort sg [[simdgroup_index_in_threadgroup]],
+    ushort ntg [[threads_per_threadgroup]]) {
+    const uint rows = ntg / 256u, slot = sg % 8u, row = group * rows + sg / 8u;
+    threadgroup float parts[16], inject[4];
+    if (tid < 4u) inject[tid] = qwen4_hc_inject_weight(inj, 4u, tid);
+    float value = 0.f;
+    if (slot <= args.n_slots && row < args.out_rows) {
+        if (slot == args.n_slots)
+            value = qwen4_row_dot(sh_down + (ulong)row * args.shared_row_bytes,
+                mid + slot * 640u, 8u, 640u, lane);
+        else value = qwen4_row_dot(down + (ulong)(uint)selected[slot] * args.expert_bytes + (ulong)row * args.row_bytes,
+                mid + slot * 640u, 10u, 640u, lane);
+    }
+    if (!lane) parts[sg] = value;
+    threadgroup_barrier(mem_flags::mem_threadgroup);
+    if (tid < rows) {
+        const uint r = group * rows + tid;
+        if (r >= args.out_rows) return;
+        float acc = 0.f;
+        for (uint s = 0; s < args.n_slots; ++s) acc += weights[s] * parts[tid * 8u + s];
+        acc += qwen4_sigmoid(sh_gate[0]) * parts[tid * 8u + args.n_slots];
+        out[r] = acc;
+        for (uint s = 0; s < 4u; ++s) R[s * args.out_rows + r] += inject[s] * acc;
+    }
+}
+
+kernel void kernel_qwen4_hc_down_partial(
+    constant uint &unused, device const half4 *w, device const float4 *x, device float *partial,
+    uint3 group [[threadgroup_position_in_grid]], ushort lane [[thread_index_in_simdgroup]],
+    ushort sg [[simdgroup_index_in_threadgroup]]) {
+    const uint row0 = (group.x * 4u + sg) * 2u;
+    const uint virtual_sg = group.y;
+    const uint ix = lane / 2u, il = lane % 2u;
+    float sums[2] = {0.f, 0.f};
+    for (uint ib = virtual_sg * 16u + ix; ib < 320u; ib += 128u) {
+        const uint base = (ib * 32u + il * 16u) / 4u;
+        float4 yl[4];
+        for (short i = 0; i < 4; ++i) yl[i] = x[base + i];
+        for (short row = 0; row < 2; ++row) {
+            float v = 0.f;
+            FOR_UNROLL (short i = 0; i < 4; ++i) v += dot(float4(w[(row0 + row) * 2560u + base + i]), yl[i]);
+            sums[row] += v;
+        }
+    }
+    for (short row = 0; row < 2; ++row) {
+        const float v = simd_sum(sums[row]);
+        if (!lane) partial[(row0 + row) * 8u + virtual_sg] = v;
+    }
+}
+
+template <typename W>
+kernel void kernel_qwen4_hc_gate_mix_split(
+        constant ds4_metal_args_qwen4_hc_gate_mix & args,
+        device const float *xn,       /* [T][hc*E] */
+        device const float *lo,       /* [T][n_rank] raw */
+        device const char  *w_up,     /* [hc*E][n_rank] */
+        device float       *mixed,    /* [T][E] */
+        threadgroup float *activated [[threadgroup(0)]],
+        uint3 tgpig [[threadgroup_position_in_grid]],
+        ushort3 ntg [[threads_per_threadgroup]],
+        ushort sgitg [[simdgroup_index_in_threadgroup]],
+        ushort tiisg [[thread_index_in_simdgroup]]) {
+    const uint hc = args.n_hc;
+    const uint E = args.n_embd;
+    const uint nsg = ntg.x / 32;
+    const uint d = tgpig.x * nsg + sgitg;
+    const uint tok = tgpig.y;
+    for (uint r = sgitg; r < args.n_rank; r += ntg.x / 32u) {
+        const float p = tiisg < 8u ? lo[r * 8u + tiisg] : 0.f;
+        const float total = simd_sum(p);
+        if (!tiisg) activated[r] = qwen4_silu(total / (float)hc);
+    }
+    threadgroup_barrier(mem_flags::mem_threadgroup);
+    if (d >= E || tok >= args.n_tokens) return;
+    const uint s = tiisg / 8, lane = tiisg % 8;
+    const W w(w_up);
+    const uint64_t row = (uint64_t)(s * E + d) * args.n_rank;
+    float acc = 0.0f;
+    for (uint r = lane; r < args.n_rank; r += 8) acc += w.at(row + r) * activated[r];
+    acc += simd_shuffle_xor(acc, 1);
+    acc += simd_shuffle_xor(acc, 2);
+    acc += simd_shuffle_xor(acc, 4);
+    float g = qwen4_sigmoid(acc) * xn[(uint64_t)tok * E * hc + s * E + d];
+    g += simd_shuffle_xor(g, 8);
+    g += simd_shuffle_xor(g, 16);
+    if (tiisg == 0) mixed[(uint64_t)tok * E + d] = g / (float)hc;
+}
+
+#define QWEN4_HC_MIX_SPLIT_INSTANCE(SUFFIX, W) \
+template [[host_name("kernel_qwen4_hc_gate_mix_split_" #SUFFIX)]] \
+kernel void kernel_qwen4_hc_gate_mix_split<W>(constant ds4_metal_args_qwen4_hc_gate_mix &, device const float *, \
+        device const float *, device const char *, device float *, threadgroup float *, uint3, ushort3, ushort, ushort);
+QWEN4_HC_MIX_SPLIT_INSTANCE(f16, qwen4_w_f16)
+
+
+template<short NR0, typename args_t>
+void qwen4_q8_packed_impl(
+        args_t args,
+        device const char * src0,
+        device const char * src1,
+        device       char * dst,
+        threadgroup  char * shmem,
+        uint3  tgpig,
+        ushort tiisg,
+        ushort sgitg) {
+    const short NSG = FC_mul_mv_nsg;
+
+    constexpr short NW = N_SIMDWIDTH;
+    constexpr short NQ = 8;
+
+    const int nb = args.ne00/QK8_0;
+
+    const int r0 = tgpig.x*NR0;
+    const int r1 = tgpig.y;
+    const int im = tgpig.z;
+
+    const uint i12 = im%args.ne12;
+    const uint i13 = im/args.ne12;
+
+    const uint64_t offset1 = r1*args.nb11 + (i12)*args.nb12 + (i13)*args.nb13;
+
+    device const float * y = (device const float *) (src1 + offset1);
+
+    device const block_q8_0 * ax[NR0];
+    FOR_UNROLL (short row = 0; row < NR0; ++row) {
+        const uint64_t offset0 = (r0 + row)*args.nb01 + (i12/args.r2)*args.nb02 + (i13/args.r3)*args.nb03;
+
+        ax[row] = (device const block_q8_0 *) ((device char *) src0 + offset0);
+    }
+
+    float sumf[NR0] = { 0.f };
+
+    const short ix = tiisg/(NW/NQ);
+    const short il = tiisg%(NW/NQ);
+
+    const int ib0 = sgitg*NQ + ix;
+
+    float yl[NQ];
+
+    device const float * yb = y + ib0*QK8_0 + il*NQ;
+
+    for (int ib = ib0; ib < nb; ib += NSG*NQ) {
+        for (short i = 0; i < NQ; ++i) {
+            yl[i] = yb[i];
+        }
+
+        for (short row = 0; row < NR0; row++) {
+            device const int8_t * qs = ax[row][ib].qs + il*NQ;
+
+            const float4 q0 = float4(*(device const packed_char4 *)qs);
+            const float4 q1 = float4(*(device const packed_char4 *)(qs + 4));
+            float sumq = 0.f;
+            FOR_UNROLL (short i = 0; i < 4; ++i) sumq += q0[i] * yl[i];
+            FOR_UNROLL (short i = 0; i < 4; ++i) sumq += q1[i] * yl[i + 4];
+
+            sumf[row] += sumq*ax[row][ib].d;
+        }
+
+        yb += NSG*NQ*QK8_0;
+    }
+
+    device float * dst_f32 = (device float *) dst + (uint64_t)im*args.ne0*args.ne1 + (uint64_t)r1*args.ne0;
+
+    helper_mv_reduce_and_write<NR0>(dst_f32, sumf, r0, args.ne01, tiisg, sgitg, shmem);
+}
+
+
+kernel void kernel_qwen4_q8_packed(
+    constant ds4_metal_args_mul_mv &args,
+    device const char *weights, device const char *x, device char *out,
+    threadgroup char *shared [[threadgroup(0)]],
+    uint3 group [[threadgroup_position_in_grid]],
+    ushort lane [[thread_index_in_simdgroup]], ushort sg [[simdgroup_index_in_threadgroup]]) {
+    qwen4_q8_packed_impl<2, constant ds4_metal_args_mul_mv &>(args, weights, x, out, shared, group, lane, sg);
+}
+
+kernel void kernel_qwen4_gdn_front_fixed(
+        constant ds4_metal_args_qwen4_gdn_front & args,
+        device float       *qkv,      /* [T][C] raw in; conv'd, q/k normalized out */
+        device float       *state,    /* [K-1][C] */
+        device const float *conv_w,   /* [C][K] */
+        device const float *mixed,    /* [T][in_dim] */
+        device const char  *w_alpha,  /* [Hv] rows */
+        device const char  *w_beta,   /* [Hv] rows */
+        device const float *ssm_a,    /* [Hv] */
+        device const float *dt_bias,  /* [Hv] */
+        device float       *ga,       /* [T][Hv] decay out */
+        device float       *gb,       /* [T][Hv] beta out */
+        device float       *snap_state,
+        uint3 tgpig [[threadgroup_position_in_grid]],
+        ushort tid [[thread_index_in_threadgroup]],
+        ushort3 ntg [[threads_per_threadgroup]],
+        ushort sgitg [[simdgroup_index_in_threadgroup]],
+        ushort tiisg [[thread_index_in_simdgroup]]) {
+    const uint h = tgpig.x;
+    const uint Hk = 16u, Hv = 48u, D = 128u, K = 4u;
+    if (h >= Hk) return;
+    const uint C = 2 * Hk * D + Hv * D;
+    const uint per_k = Hv / Hk;
+    const uint n_ch = (2 + per_k) * D;
+    const uint nth = ntg.x;
+    const uint nsg = nth / 32;
+    const uint npt = D / 32;
+    for (uint tok = 0; tok < 1u; tok++) {
+        device float *row = qkv + (uint64_t)tok * C;
+        for (uint cl = tid; cl < n_ch; cl += nth) {
+            const uint grp = cl / D, i = cl - grp * D;
+            const uint c = (grp == 0 ? h * D : grp == 1 ? Hk * D + h * D : 2 * Hk * D + (h + (grp - 2) * Hk) * D) + i;
+            const float raw = row[c];
+            float acc = conv_w[c * K + K - 1] * raw;
+            for (uint t = 0; t + 1 < K; t++) acc += conv_w[c * K + t] * state[t * C + c];
+            for (uint t = 0; t + 2 < K; t++) state[t * C + c] = state[(t + 1) * C + c];
+            state[(K - 2) * C + c] = raw;
+            row[c] = qwen4_silu(acc);
+            if (tok == args.snap_tok) {
+                for (uint t = 0; t + 1 < K; t++) snap_state[t * C + c] = state[t * C + c];
+            }
+        }
+        threadgroup_barrier(mem_flags::mem_device);
+        if (sgitg < 2) {
+            device float *v = row + (sgitg == 0 ? h * D : Hk * D + h * D);
+            float ss = 0.0f;
+            for (uint r = 0; r < npt; r++) ss += v[tiisg + 32 * r] * v[tiisg + 32 * r];
+            ss = simd_sum(ss);
+            const float sc = rsqrt(ss + 1e-6f) * (sgitg == 0 ? rsqrt((float)D) : 1.0f);
+            for (uint r = 0; r < npt; r++) v[tiisg + 32 * r] *= sc;
+        } else {
+            device const float *x = mixed + (uint64_t)tok * 2560u;
+            for (uint rr = (uint)sgitg - 2u; rr < 2 * per_k; rr += nsg - 2u) {
+                const uint j = h + (rr / 2) * Hk;
+                device const char *wrow = (rr & 1u) ? w_beta : w_alpha;
+                const float v = qwen4_row_dot(wrow + (uint64_t)j * 2720u, x, 8u, 2560u, tiisg);
+                if (tiisg == 0) {
+                    if (rr & 1u) gb[(uint64_t)tok * Hv + j] = qwen4_sigmoid(v);
+                    else ga[(uint64_t)tok * Hv + j] = exp(ssm_a[j] * qwen4_softplus(v + dt_bias[j]));
+                }
+            }
+        }
+        threadgroup_barrier(mem_flags::mem_device);
+    }
+}
+
+kernel void kernel_qwen4_gdn_front_z(
+        constant ds4_metal_args_qwen4_gdn_front & args,
+        device float       *qkv,      /* [T][C] raw in; conv'd, q/k normalized out */
+        device float       *state,    /* [K-1][C] */
+        device const float *conv_w,   /* [C][K] */
+        device const float *mixed,    /* [T][in_dim] */
+        device const char  *w_alpha,  /* [Hv] rows */
+        device const char  *w_beta,   /* [Hv] rows */
+        device const float *ssm_a,    /* [Hv] */
+        device const float *dt_bias,  /* [Hv] */
+        device float       *ga,       /* [T][Hv] decay out */
+        device float       *gb,       /* [T][Hv] beta out */
+        device float       *snap_state,
+        device const block_q8_0 *wz, device float *z,
+        uint3 tgpig [[threadgroup_position_in_grid]],
+        ushort tid [[thread_index_in_threadgroup]],
+        ushort3 ntg [[threads_per_threadgroup]],
+        ushort sgitg [[simdgroup_index_in_threadgroup]],
+        ushort tiisg [[thread_index_in_simdgroup]]) {
+    if (tgpig.x >= 16u) {
+        const uint cohort = sgitg / 4u, sg = sgitg % 4u;
+        const uint r0 = (tgpig.x - 16u) * 4u + cohort * 2u;
+        const uint ix = tiisg / 4u, il = tiisg % 4u;
+        float sums[2] = {0.f, 0.f};
+        for (uint ib = sg * 8u + ix; ib < 80u; ib += 32u) {
+            float yl[8];
+            for (short i = 0; i < 8; ++i) yl[i] = mixed[ib * 32u + il * 8u + i];
+            for (short row = 0; row < 2; ++row) {
+                device const block_q8_0 &w = wz[(r0 + row) * 80u + ib];
+                float sumq = 0.f;
+                FOR_UNROLL (short i = 0; i < 8; ++i) sumq += w.qs[il * 8u + i] * yl[i];
+                sums[row] += sumq * w.d;
+            }
+        }
+        threadgroup float shared[128];
+        for (short row = 0; row < 2; ++row) {
+            if (!sg) shared[cohort * 64u + row * 32u + tiisg] = 0.f;
+            sums[row] = simd_sum(sums[row]);
+        }
+        threadgroup_barrier(mem_flags::mem_threadgroup);
+        for (short row = 0; row < 2; ++row) if (!tiisg) shared[cohort * 64u + row * 32u + sg] = sums[row];
+        threadgroup_barrier(mem_flags::mem_threadgroup);
+        for (short row = 0; row < 2; ++row) {
+            const float total = simd_sum(shared[cohort * 64u + row * 32u + tiisg]);
+            if (!sg && !tiisg) z[r0 + row] = total;
+        }
+        return;
+    }
+    const uint h = tgpig.x;
+    const uint Hk = 16u, Hv = 48u, D = 128u, K = 4u;
+    if (h >= Hk) return;
+    const uint C = 2 * Hk * D + Hv * D;
+    const uint per_k = Hv / Hk;
+    const uint n_ch = (2 + per_k) * D;
+    const uint nth = ntg.x;
+    const uint nsg = nth / 32;
+    const uint npt = D / 32;
+    for (uint tok = 0; tok < 1u; tok++) {
+        device float *row = qkv + (uint64_t)tok * C;
+        for (uint cl = tid; cl < n_ch; cl += nth) {
+            const uint grp = cl / D, i = cl - grp * D;
+            const uint c = (grp == 0 ? h * D : grp == 1 ? Hk * D + h * D : 2 * Hk * D + (h + (grp - 2) * Hk) * D) + i;
+            const float raw = row[c];
+            float acc = conv_w[c * K + K - 1] * raw;
+            for (uint t = 0; t + 1 < K; t++) acc += conv_w[c * K + t] * state[t * C + c];
+            for (uint t = 0; t + 2 < K; t++) state[t * C + c] = state[(t + 1) * C + c];
+            state[(K - 2) * C + c] = raw;
+            row[c] = qwen4_silu(acc);
+            if (tok == args.snap_tok) {
+                for (uint t = 0; t + 1 < K; t++) snap_state[t * C + c] = state[t * C + c];
+            }
+        }
+        threadgroup_barrier(mem_flags::mem_device);
+        if (sgitg < 2) {
+            device float *v = row + (sgitg == 0 ? h * D : Hk * D + h * D);
+            float ss = 0.0f;
+            for (uint r = 0; r < npt; r++) ss += v[tiisg + 32 * r] * v[tiisg + 32 * r];
+            ss = simd_sum(ss);
+            const float sc = rsqrt(ss + 1e-6f) * (sgitg == 0 ? rsqrt((float)D) : 1.0f);
+            for (uint r = 0; r < npt; r++) v[tiisg + 32 * r] *= sc;
+        } else {
+            device const float *x = mixed + (uint64_t)tok * 2560u;
+            for (uint rr = (uint)sgitg - 2u; rr < 2 * per_k; rr += nsg - 2u) {
+                const uint j = h + (rr / 2) * Hk;
+                device const char *wrow = (rr & 1u) ? w_beta : w_alpha;
+                const float v = qwen4_row_dot(wrow + (uint64_t)j * 2720u, x, 8u, 2560u, tiisg);
+                if (tiisg == 0) {
+                    if (rr & 1u) gb[(uint64_t)tok * Hv + j] = qwen4_sigmoid(v);
+                    else ga[(uint64_t)tok * Hv + j] = exp(ssm_a[j] * qwen4_softplus(v + dt_bias[j]));
+                }
+            }
+        }
+        threadgroup_barrier(mem_flags::mem_device);
+    }
+}
+
+kernel void kernel_qwen4_expand_iq2(
+    constant uint2 &args, device const uchar *src, device uchar *dst,
+    uint tid [[thread_position_in_grid]]) {
+    if (tid >= args.x) return;
+    device const uchar *block = src + (ulong)(tid / 8u) * 66u;
+    device const ushort *q2 = (device const ushort *)(block + 2u) + (tid % 8u) * 4u;
+    const uint g = (uint)q2[0] | ((uint)q2[1] << 16);
+    const uint a = (uint)q2[2] | ((uint)q2[3] << 16);
+    const float d = (float)*(device const half *)block;
+    const float dl = d * (0.5f + (float)(a >> 28)) * 0.25f;
+    device uchar *out = dst + (ulong)tid * (args.y == 2u ? 12u : 36u);
+    *(device float *)out = dl;
+    for (uint j = 0; j < 4; ++j) {
+        constant const uchar *grid = (constant const uchar *)(ds4_metal_iq2xxs_grid + ((g >> (8u * j)) & 255u));
+        const uint signs = ds4_metal_ksigns_iq2xs[(a >> (7u * j)) & 127u];
+        if (args.y == 2u) { out[4u + j] = (uchar)((g >> (8u * j)) & 255u); out[8u + j] = (uchar)signs; }
+        else for (uint i = 0; i < 8; ++i)
+            ((device char *)(out + 4u))[j * 8u + i] = (char)((signs >> i) & 1u ? -(int)grid[i] : (int)grid[i]);
+    }
+}

